-- 038 · Catálogo geográfico oficial (Pais/Provincia/Municipio/CP) para reemplazar
-- el uso de `poblaciones`/`codigos_postales` (datos sucios heredados de GELITE,
-- ver auditoría 27-sep-2026: duplicados, erratas, CPs mal vinculados a municipios
-- equivocados). Las tablas viejas NO se tocan ni se borran — siguen ahí como legado
-- hasta que se migren los usos existentes (informes). Datos importados de fuentes
-- oficiales: países ISO 3166-1, provincias/municipios INE (Callejero del Censo
-- Electoral), CP↔municipio del mismo Callejero (dataset inigoflores/ds-codigos-
-- postales-ine-es, que cita al INE como fuente).

CREATE TABLE IF NOT EXISTS paises (
    id SERIAL PRIMARY KEY,
    iso2 VARCHAR(2) NOT NULL UNIQUE,
    nombre VARCHAR(120) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_paises_nombre ON paises (nombre);

CREATE TABLE IF NOT EXISTS provincias (
    id SERIAL PRIMARY KEY,
    pais_id INTEGER NOT NULL REFERENCES paises(id),
    ine_id VARCHAR(5) NOT NULL,
    nombre VARCHAR(120) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_provincias_pais ON provincias (pais_id);
CREATE INDEX IF NOT EXISTS ix_provincias_nombre ON provincias (nombre);

CREATE TABLE IF NOT EXISTS municipios (
    id SERIAL PRIMARY KEY,
    provincia_id INTEGER NOT NULL REFERENCES provincias(id),
    ine_id VARCHAR(5) NOT NULL,
    nombre VARCHAR(150) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_municipios_provincia ON municipios (provincia_id);
CREATE INDEX IF NOT EXISTS ix_municipios_nombre ON municipios (nombre);

CREATE TABLE IF NOT EXISTS codigos_postales_geo (
    id SERIAL PRIMARY KEY,
    cp VARCHAR(5) NOT NULL,
    municipio_id INTEGER NOT NULL REFERENCES municipios(id),
    created_at TIMESTAMP NOT NULL DEFAULT now(),
    updated_at TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_cpgeo_cp ON codigos_postales_geo (cp);
CREATE INDEX IF NOT EXISTS ix_cpgeo_municipio ON codigos_postales_geo (municipio_id);


-- Unicidad natural para conservar relaciones estables al reimportar el catálogo.
CREATE UNIQUE INDEX IF NOT EXISTS uq_provincias_pais_ine ON provincias (pais_id, ine_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_municipios_provincia_ine ON municipios (provincia_id, ine_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_cpgeo_cp_municipio ON codigos_postales_geo (cp, municipio_id);

-- Snapshot idempotente del catálogo geográfico oficial que alimenta la aplicación.
-- Fuente del snapshot: tablas geo ya importadas en la BD de MakingSmiles; datos públicos.
BEGIN;

